#define PAGE_SIZE 4096

void *addr;
size_t length = PAGE_SIZE * 10;

// 1. Create a region to unmap
addr = mmap(NULL, length, PROT_READ | PROT_WRITE, 
            MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

if (addr == MAP_FAILED) { /* handle error */ }

// 2. Remove the virtual memory mapping
int status = munmap(addr, length);

if (status == -1) {
    // EINVAL: addr not page aligned or length is zero/invalid.
    // EFAULT: Internal kernel error.
    perror("munmap failed");
}

// addr is now an invalid pointer.
